import { describe, expect, test } from "bun:test";
import {
  OpeningHoursError,
  parseOpeningHours,
  type OpeningHoursErrorCode,
  type WeeklyHours,
} from "./openingHours";

test("errors report the column in their message", () => {
  const error = new OpeningHoursError("UNKNOWN_DAY", 4, 'Unknown day "Fx"');
  expect(error).toBeInstanceOf(Error);
  expect(error.code).toBe("UNKNOWN_DAY");
  expect(error.column).toBe(4);
  expect(error.message).toBe('Unknown day "Fx" (column 4)');
});

function week(open: Partial<WeeklyHours>): WeeklyHours {
  return { Mo: [], Tu: [], We: [], Th: [], Fr: [], Sa: [], Su: [], ...open };
}

describe("parseOpeningHours", () => {
  test("one day with one range returns all seven days, the others closed", () => {
    expect(parseOpeningHours("Mo 08:00-12:00")).toEqual(
      week({ Mo: [{ from: "08:00", to: "12:00" }] }),
    );
  });
});
EOF
